<script lang="ts">
	import { onMount } from 'svelte'; import { createUser, users } from '$lib/api/users'; import type { Role, User } from '$lib/api/types'; import Button from '$lib/components/ui/Button.svelte'; import Card from '$lib/components/ui/Card.svelte'; import Input from '$lib/components/ui/Input.svelte'; import Select from '$lib/components/ui/Select.svelte'; import Alert from '$lib/components/ui/Alert.svelte';
	let items = $state<User[]>([]); let loading = $state(true); let error = $state(''); let name = $state(''); let email = $state(''); let password = $state(''); let role = $state<Role>('CUSTOMER'); let saving = $state(false); async function load() { loading = true; try { items = (await users()).content; } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not load users.'; } finally { loading = false; } } onMount(load);
	async function save() { saving = true; error = ''; try { await createUser(email, password, name, role); name = ''; email = ''; password = ''; role = 'CUSTOMER'; await load(); } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not create user.'; } finally { saving = false; } }
</script>
<div class="space-y-5"><div><h1 class="text-2xl font-semibold">Users</h1><p class="text-sm text-slate-600">Create and view system users.</p></div>{#if error}<Alert>{error}</Alert>{/if}<div class="grid gap-5 lg:grid-cols-[1fr_20rem]"><Card>{#if loading}<p class="text-sm text-slate-500">Loading users…</p>{:else}<div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b text-slate-500"><tr><th class="p-2">Name</th><th class="p-2">Email</th><th class="p-2">Role</th></tr></thead><tbody>{#each items as user}<tr class="border-b"><td class="p-2">{user.name}</td><td class="p-2">{user.email}</td><td class="p-2">{user.role}</td></tr>{/each}</tbody></table></div>{/if}</Card><Card><form class="space-y-3" onsubmit={(event) => { event.preventDefault(); save(); }}><h2 class="font-semibold">Create user</h2><label class="block text-sm">Name <Input bind:value={name} required /></label><label class="block text-sm">Email <Input bind:value={email} type="email" required /></label><label class="block text-sm">Password <Input bind:value={password} type="password" minlength={8} required /></label><label class="block text-sm">Role <Select bind:value={role}><option value="CUSTOMER">Customer</option><option value="ADMIN">Admin</option></Select></label><Button type="submit" disabled={saving}>{saving ? 'Creating…' : 'Create user'}</Button></form></Card></div></div>
